INSERT INTO `t_message_info` (`KEY`, `KOR`, `ENG`, `VIET`, `JPN`, `THA`, `CHN`, `COMMENT`, `REG_DATE`, `LAST_MIDOFY_DATE`) VALUES ('GK_ALLOC_BAND_DESC', 'P_A = 합계 − 차감. 배부기준 비중으로 나누고 마지막 행이 반올림 차액을 받습니다.', 'P_A = total − reduction. Split by the basis weight; the last row takes the rounding remainder.', 'P_A = total − reduction; chia theo tỷ trọng tiêu thức; dòng cuối nhận phần dư làm tròn.', 'P_A = 合計 − 控除。配賦基準の比率で按分し、端数は最終行が受けます。', 'P_A = ยอดรวม − รายการหัก แบ่งตามสัดส่วนเกณฑ์ แถวสุดท้ายรับเศษปัดเศษ', 'P_A = 合计 − 调减。按分配标准比重分摊，尾差计入最后一行。', '26-11-16 Simple costing', '2026-11-16 13:24:00', NULL);
