INSERT INTO `t_message_info` (`KEY`, `KOR`, `ENG`, `VIET`, `JPN`, `THA`, `CHN`, `COMMENT`, `REG_DATE`, `LAST_MIDOFY_DATE`) VALUES ('GK_ALLOC_DONE', '배부가 확정되었습니다. 3/4단계는 계정과 완제품 코드별 상세를 읽습니다.', 'Allocation is confirmed. Steps 3 and 4 read the detail by account and product code.', 'Đã xác nhận phân bổ. Bước 3/4 đọc kết quả chi tiết theo từng TK và mã TP.', '配賦を確定しました。工程3/4は勘定と完成品コード別の明細を読みます。', 'ยืนยันการปันส่วนแล้ว ขั้น 3/4 อ่านรายละเอียดตามบัญชีและรหัสสินค้า', '已确认分摊。第3/4步按科目和成品编码读取明细。', '26-11-16 Simple costing', '2026-11-16 13:24:00', NULL);
