INSERT INTO `t_message_info` (`KEY`, `KOR`, `ENG`, `VIET`, `JPN`, `THA`, `CHN`, `COMMENT`, `REG_DATE`, `LAST_MIDOFY_DATE`) VALUES ('GK_HINT_NVL', '주요 원자재 기준은 완제품 코드별 출고액 N621/C152입니다. 이론 BOM 비율은 쓰지 않습니다.', 'The main-material basis is the issue amount Dr 621 / Cr 152 by product code. The theoretical BOM rate is not used.', 'Tiêu thức NVL chính lấy từ giá trị xuất N621/C152 theo mã TP — không dùng tỷ lệ BOM lý thuyết.', '主要原材料の基準は完成品コード別の出庫額（借方621/貸方152）です。理論BOM比率は使いません。', 'เกณฑ์วัตถุดิบหลักใช้มูลค่าเบิกตามรหัสสินค้า เดบิต 621 / เครดิต 152 ไม่ใช้อัตรา BOM ตามทฤษฎี', '主要原材料标准取各成品编码的出库金额（借621/贷152），不用理论 BOM 比例。', '26-11-16 Simple costing', '2026-11-16 13:24:00', NULL);
INSERT INTO `t_message_info` (`KEY`, `KOR`, `ENG`, `VIET`, `JPN`, `THA`, `CHN`, `COMMENT`, `REG_DATE`, `LAST_MIDOFY_DATE`) VALUES ('GK_HINT_QTY', '입고 완제품 기준은 완제품 코드별 입고 수량 N155/C154입니다.', 'The receipt-qty basis is the receipt quantity Dr 155 / Cr 154 by product code.', 'Tiêu thức TPNK lấy từ số lượng nhập N155/C154 theo mã TP.', '入庫数量の基準は完成品コード別の入庫数量（借方155/貸方154）です。', 'เกณฑ์จำนวนรับเข้าใช้จำนวนรับ เดบิต 155 / เครดิต 154 ตามรหัสสินค้า', '入库数量标准取各成品编码的入库数量（借155/贷154）。', '26-11-16 Simple costing', '2026-11-16 13:24:00', NULL);
