INSERT INTO `t_message_info` (`KEY`, `KOR`, `ENG`, `VIET`, `JPN`, `THA`, `CHN`, `COMMENT`, `REG_DATE`, `LAST_MIDOFY_DATE`) VALUES ('GK_SHARED_NOTE', '역순으로 다시 엽니다. PeriodLock에서 B1/B6이 DONE이면 먼저 마감을 해제해야 하며, 원복 전에는 G-K가 성공으로 보고하지 않습니다.', 'Reopen in reverse order. If B1/B6 is DONE on PeriodLock, unlock it first. G-K does not report success until the reversal is done.', 'Mở lại theo thứ tự ngược. B1/B6 đang DONE trên PeriodLock phải mở sổ trước — G-K không báo thành công nếu chưa hoàn nguyên.', '逆順で再開します。PeriodLock で B1/B6 が DONE なら先に締めを解除してください。戻す前は G-K は成功にしません。', 'เปิดใหม่จากหลังไปหน้า ถ้า B1/B6 เป็น DONE บน PeriodLock ต้องปลดล็อกก่อน G-K จะไม่รายงานสำเร็จจนกว่าจะย้อนกลับ', '按相反顺序重开。若 PeriodLock 上 B1/B6 为 DONE，须先解锁。未还原前 G-K 不报成功。', '26-11-16 Simple costing', '2026-11-16 13:24:00', NULL);
