INSERT INTO `t_message_info` (`KEY`, `KOR`, `ENG`, `VIET`, `JPN`, `THA`, `CHN`, `COMMENT`, `REG_DATE`, `LAST_MIDOFY_DATE`) VALUES ('GK_STEP1_BAND_DESC', '이 단계는 PeriodLock FA_PREPAID_LOCK을 호출합니다. DB가 DONE을 돌려줄 때만 DONE으로 표시합니다.', 'This step calls PeriodLock FA_PREPAID_LOCK. DONE is shown only when the database returns DONE.', 'Bước này gọi PeriodLock FA_PREPAID_LOCK. Trạng thái DONE chỉ hiện khi DB trả về DONE.', 'この工程は PeriodLock FA_PREPAID_LOCK を呼びます。DB が DONE を返したときだけ DONE と表示します。', 'ขั้นตอนนี้เรียก PeriodLock FA_PREPAID_LOCK แสดง DONE เฉพาะเมื่อฐานข้อมูลคืนค่า DONE', '本步调用 PeriodLock FA_PREPAID_LOCK。仅当数据库返回 DONE 时才显示 DONE。', '26-11-16 Simple costing', '2026-11-16 13:24:00', NULL);
