INSERT INTO `t_message_info` (`KEY`, `KOR`, `ENG`, `VIET`, `JPN`, `THA`, `CHN`, `COMMENT`, `REG_DATE`, `LAST_MIDOFY_DATE`) VALUES ('GK_STEP1_HINT', '순서: 점검 → 미리보기 → 실행. PeriodLock과 DB가 끝났다고 할 때만 DONE입니다.', 'Order: Check → Preview → Execute. DONE only when PeriodLock and the database report completion.', 'Thứ tự: Kiểm tra → Xem trước → Thực hiện. DONE chỉ khi PeriodLock và DB báo xong.', '順序: 確認 → プレビュー → 実行。PeriodLock と DB が完了を返したときだけ DONE です。', 'ลำดับ: ตรวจสอบ → ดูล่วงหน้า → ดำเนินการ เป็น DONE เมื่อ PeriodLock และฐานข้อมูลรายงานว่าเสร็จ', '顺序：检查 → 预览 → 执行。仅当 PeriodLock 和数据库报告完成时才是 DONE。', '26-11-16 Simple costing', '2026-11-16 13:24:00', NULL);
INSERT INTO `t_message_info` (`KEY`, `KOR`, `ENG`, `VIET`, `JPN`, `THA`, `CHN`, `COMMENT`, `REG_DATE`, `LAST_MIDOFY_DATE`) VALUES ('GK_STEP1_OK', 'PeriodLock이 1단계를 기록했습니다.', 'PeriodLock recorded step 1.', 'PeriodLock đã ghi nhận bước 1.', 'PeriodLock が工程1を記録しました。', 'PeriodLock บันทึกขั้นตอนที่ 1 แล้ว', 'PeriodLock 已记录第1步。', '26-11-16 Simple costing', '2026-11-16 13:24:00', NULL);
INSERT INTO `t_message_info` (`KEY`, `KOR`, `ENG`, `VIET`, `JPN`, `THA`, `CHN`, `COMMENT`, `REG_DATE`, `LAST_MIDOFY_DATE`) VALUES ('GK_STEP1_PREVIEW_OK', '차변 627 / 대변 214, 242를 미리 보았습니다.', 'Previewed Dr 627 / Cr 214 and 242.', 'Đã xem trước Nợ 627 / Có 214, 242.', '借方 627 / 貸方 214、242 をプレビューしました。', 'ดูรายการเดบิต 627 / เครดิต 214, 242 ล่วงหน้าแล้ว', '已预览借 627 / 贷 214、242。', '26-11-16 Simple costing', '2026-11-16 13:24:00', NULL);
INSERT INTO `t_message_info` (`KEY`, `KOR`, `ENG`, `VIET`, `JPN`, `THA`, `CHN`, `COMMENT`, `REG_DATE`, `LAST_MIDOFY_DATE`) VALUES ('GK_STEP1_REOPENED', '1단계를 다시 열었습니다. 기존 결과는 유지됩니다. 점검 → 미리보기 → 다시 실행하면 덮어씁니다.', 'Step 1 was reopened. The old result is kept. Check → Preview → Execute again to overwrite.', 'Bước 1 đã mở lại — kết quả cũ được giữ. Kiểm tra → Xem trước → Thực hiện lại để ghi đè.', '工程1を再開しました。以前の結果は残ります。確認 → プレビュー → 再実行で上書きします。', 'เปิดขั้นตอนที่ 1 ใหม่แล้ว เก็บผลเดิม ตรวจสอบ → ดูล่วงหน้า → ทำใหม่เพื่อเขียนทับ', '第1步已重开，原结果保留。检查 → 预览 → 再次执行即可覆盖。', '26-11-16 Simple costing', '2026-11-16 13:24:00', NULL);
INSERT INTO `t_message_info` (`KEY`, `KOR`, `ENG`, `VIET`, `JPN`, `THA`, `CHN`, `COMMENT`, `REG_DATE`, `LAST_MIDOFY_DATE`) VALUES ('GK_STEP1_RUN', '1단계 마감 실행', 'Run step 1 lock', 'Thực hiện khóa bước 1', '工程1の締めを実行', 'ดำเนินการล็อกขั้นตอนที่ 1', '执行第1步锁定', '26-11-16 Simple costing', '2026-11-16 13:24:00', NULL);
