INSERT INTO `t_message_info` (`KEY`, `KOR`, `ENG`, `VIET`, `JPN`, `THA`, `CHN`, `COMMENT`, `REG_DATE`, `LAST_MIDOFY_DATE`) VALUES ('GK_STEP3_BAND', '생산 규칙 EXP_TO_154_ONLY로 2단계 마감', 'Lock step 2 with the production rule EXP_TO_154_ONLY', 'Khóa bước 2 theo rule sản xuất EXP_TO_154_ONLY', '生産ルール EXP_TO_154_ONLY で工程2を締め', 'ล็อกขั้นตอนที่ 2 ตามกฎการผลิต EXP_TO_154_ONLY', '按生产规则 EXP_TO_154_ONLY 锁定第2步', '26-11-16 Simple costing', '2026-11-16 13:24:00', NULL);
INSERT INTO `t_message_info` (`KEY`, `KOR`, `ENG`, `VIET`, `JPN`, `THA`, `CHN`, `COMMENT`, `REG_DATE`, `LAST_MIDOFY_DATE`) VALUES ('GK_STEP3_BAND_DESC', '같은 트랜잭션에서 PeriodLock으로 EXP_TO_154_ONLY를 기록합니다. 154를 155 또는 632로 대체하지 않습니다.', 'Posts EXP_TO_154_ONLY through PeriodLock in the same transaction. Does not transfer 154 to 155 or 632.', 'Ghi EXP_TO_154_ONLY qua PeriodLock trên cùng transaction. Không kết chuyển 154 sang 155 hoặc 632.', '同一トランザクションで PeriodLock により EXP_TO_154_ONLY を記録します。154 を 155 または 632 へは振り替えません。', 'บันทึก EXP_TO_154_ONLY ผ่าน PeriodLock ในธุรกรรมเดียวกัน ไม่โอน 154 ไป 155 หรือ 632', '在同一事务中通过 PeriodLock 写入 EXP_TO_154_ONLY。不把 154 结转到 155 或 632。', '26-11-16 Simple costing', '2026-11-16 13:24:00', NULL);
INSERT INTO `t_message_info` (`KEY`, `KOR`, `ENG`, `VIET`, `JPN`, `THA`, `CHN`, `COMMENT`, `REG_DATE`, `LAST_MIDOFY_DATE`) VALUES ('GK_STEP3_CHECK_OK', '비용 마감 조건이 유효합니다.', 'The cost-lock conditions are valid.', 'Điều kiện khóa chi phí hợp lệ.', '費用締めの条件は有効です。', 'เงื่อนไขล็อกค่าใช้จ่ายถูกต้อง', '费用锁定条件有效。', '26-11-16 Simple costing', '2026-11-16 13:24:00', NULL);
INSERT INTO `t_message_info` (`KEY`, `KOR`, `ENG`, `VIET`, `JPN`, `THA`, `CHN`, `COMMENT`, `REG_DATE`, `LAST_MIDOFY_DATE`) VALUES ('GK_STEP3_CONFIRM', 'EXP_TO_154_ONLY에 따라 621/622/627을 154로 대체합니다. 154→155 또는 154→632는 만들지 않습니다. 계속하시겠습니까?', 'Transfer 621/622/627 to 154 under EXP_TO_154_ONLY. 154→155 and 154→632 are not created. Continue?', 'Kết chuyển 621/622/627 sang 154 theo EXP_TO_154_ONLY. Không sinh 154→155 hoặc 154→632. Tiếp tục?', 'EXP_TO_154_ONLY に従い 621/622/627 を 154 へ振り替えます。154→155 と 154→632 は作りません。続けますか？', 'โอน 621/622/627 ไป 154 ตาม EXP_TO_154_ONLY ไม่สร้าง 154→155 หรือ 154→632 ดำเนินการต่อหรือไม่', '按 EXP_TO_154_ONLY 将 621/622/627 结转到 154。不生成 154→155 或 154→632。是否继续？', '26-11-16 Simple costing', '2026-11-16 13:24:00', NULL);
INSERT INTO `t_message_info` (`KEY`, `KOR`, `ENG`, `VIET`, `JPN`, `THA`, `CHN`, `COMMENT`, `REG_DATE`, `LAST_MIDOFY_DATE`) VALUES ('GK_STEP3_DONE', '154로 대체했습니다. 같은 기간을 다시 실행하면 같은 STABLE_KEY를 갱신하고 두 번째 전표는 만들지 않습니다.', 'Transferred to 154. Running the same period again updates the same STABLE_KEY and does not create a second voucher.', 'Đã kết chuyển 154. Chạy lại cùng kỳ cập nhật đúng STABLE_KEY, không tạo chứng từ thứ hai.', '154 へ振り替えました。同じ期間を再実行すると同じ STABLE_KEY を更新し、2枚目の伝票は作りません。', 'โอนเข้า 154 แล้ว รันงวดเดิมอีกครั้งจะอัปเดต STABLE_KEY เดิม และไม่สร้างเอกสารที่สอง', '已结转到 154。同一期间再次运行会更新同一 STABLE_KEY，不生成第二张凭证。', '26-11-16 Simple costing', '2026-11-16 13:24:00', NULL);
INSERT INTO `t_message_info` (`KEY`, `KOR`, `ENG`, `VIET`, `JPN`, `THA`, `CHN`, `COMMENT`, `REG_DATE`, `LAST_MIDOFY_DATE`) VALUES ('GK_STEP3_NEED_CHECK', '대체를 기록하기 전에 조건을 점검하십시오.', 'Check the conditions before posting the transfer.', 'Chạy kiểm tra điều kiện trước khi ghi nhận kết chuyển.', '振替を記録する前に条件を確認してください。', 'ตรวจสอบเงื่อนไขก่อนบันทึกการโอน', '记账结转前请先检查条件。', '26-11-16 Simple costing', '2026-11-16 13:24:00', NULL);
INSERT INTO `t_message_info` (`KEY`, `KOR`, `ENG`, `VIET`, `JPN`, `THA`, `CHN`, `COMMENT`, `REG_DATE`, `LAST_MIDOFY_DATE`) VALUES ('GK_STEP3_OK', '서버가 154 대체를 기록했습니다.', 'The server recorded the transfer to 154.', 'Backend đã ghi nhận kết chuyển 154.', 'サーバーが 154 への振替を記録しました。', 'เซิร์ฟเวอร์บันทึกการโอนเข้า 154 แล้ว', '服务器已记录结转到 154。', '26-11-16 Simple costing', '2026-11-16 13:24:00', NULL);
INSERT INTO `t_message_info` (`KEY`, `KOR`, `ENG`, `VIET`, `JPN`, `THA`, `CHN`, `COMMENT`, `REG_DATE`, `LAST_MIDOFY_DATE`) VALUES ('GK_STEP3_READY', '조건 점검 결과 유효합니다. 비용을 154로 마감할 수 있습니다.', 'The check passed. Costs can be locked to 154.', 'Đã kiểm tra điều kiện: hợp lệ. Có thể khóa chi phí → 154.', '条件確認は有効です。費用を 154 へ締められます。', 'ตรวจสอบเงื่อนไขแล้ว ถูกต้อง สามารถล็อกค่าใช้จ่ายไป 154', '条件检查通过。可以将费用锁定到 154。', '26-11-16 Simple costing', '2026-11-16 13:24:00', NULL);
