INSERT INTO `t_message_info` (`KEY`, `KOR`, `ENG`, `VIET`, `JPN`, `THA`, `CHN`, `COMMENT`, `REG_DATE`, `LAST_MIDOFY_DATE`) VALUES ('GK_STEP4_BAND', '제조원가를 계산하고 완제품 입고전표에 단가를 기록', 'Calculate product cost and write the price on the finished-goods receipt', 'Tính giá thành và ghi giá vào phiếu nhập thành phẩm', '製造原価を計算し、完成品入庫伝票に単価を記録', 'คำนวณต้นทุนและบันทึกราคาในใบรับสินค้าสำเร็จรูป', '计算成本并把单价写入产成品入库单', '26-11-16 Simple costing', '2026-11-16 13:24:00', NULL);
INSERT INTO `t_message_info` (`KEY`, `KOR`, `ENG`, `VIET`, `JPN`, `THA`, `CHN`, `COMMENT`, `REG_DATE`, `LAST_MIDOFY_DATE`) VALUES ('GK_STEP4_BAND_DESC', 'TOTAL_COST = ROUND(BEFORE_154 + TOTAL_INCURRED − CLOSING_154, 0). 622/627은 2단계에서 가져오며 3단계 대체와 중복 가산하지 않습니다.', 'TOTAL_COST = ROUND(BEFORE_154 + TOTAL_INCURRED − CLOSING_154, 0). Accounts 622/627 come from step 2 and are not added again from the step 3 transfer.', 'TOTAL_COST = ROUND(BEFORE_154 + TOTAL_INCURRED − CLOSING_154, 0). Nguồn 622/627 từ Bước 2 — không cộng trùng kết chuyển Bước 3.', 'TOTAL_COST = ROUND(BEFORE_154 + TOTAL_INCURRED − CLOSING_154, 0)。622/627 は工程2から取り、工程3の振替とは二重計上しません。', 'TOTAL_COST = ROUND(BEFORE_154 + TOTAL_INCURRED − CLOSING_154, 0) บัญชี 622/627 มาจากขั้น 2 ไม่บวกซ้ำกับการโอนขั้น 3', 'TOTAL_COST = ROUND(BEFORE_154 + TOTAL_INCURRED − CLOSING_154, 0)。622/627 来自第2步，不与第3步结转重复加计。', '26-11-16 Simple costing', '2026-11-16 13:24:00', NULL);
INSERT INTO `t_message_info` (`KEY`, `KOR`, `ENG`, `VIET`, `JPN`, `THA`, `CHN`, `COMMENT`, `REG_DATE`, `LAST_MIDOFY_DATE`) VALUES ('GK_STEP4_CONFIRM', 'INPUT_ID {0}건의 원가 스냅샷을 저장하시겠습니까? 이 단계는 아직 재고를 갱신하지 않습니다.', 'Save the cost snapshot for {0} INPUT_ID slips? This step does not update inventory yet.', 'Xác nhận lưu snapshot giá thành của {0} phiếu INPUT_ID? Bước này chưa cập nhật kho.', 'INPUT_ID {0} 件の原価スナップショットを保存しますか？この工程はまだ在庫を更新しません。', 'บันทึกสแนปชอตต้นทุนของ INPUT_ID {0} ใบหรือไม่ ขั้นตอนนี้ยังไม่อัปเดตคลัง', '保存 {0} 张 INPUT_ID 的成本快照？本步尚未更新库存。', '26-11-16 Simple costing', '2026-11-16 13:24:00', NULL);
INSERT INTO `t_message_info` (`KEY`, `KOR`, `ENG`, `VIET`, `JPN`, `THA`, `CHN`, `COMMENT`, `REG_DATE`, `LAST_MIDOFY_DATE`) VALUES ('GK_STEP4_DONE', '원가 스냅샷 {0}. 이 단계에서는 재고가 바뀌지 않습니다.', 'Cost snapshot {0}. Inventory is unchanged at this step.', 'Snapshot giá thành {0} đ. Kho chưa đổi ở bước này.', '原価スナップショット {0}。この工程では在庫は変わりません。', 'สแนปชอตต้นทุน {0} คลังยังไม่เปลี่ยนในขั้นตอนนี้', '成本快照 {0}。本步库存未变。', '26-11-16 Simple costing', '2026-11-16 13:24:00', NULL);
INSERT INTO `t_message_info` (`KEY`, `KOR`, `ENG`, `VIET`, `JPN`, `THA`, `CHN`, `COMMENT`, `REG_DATE`, `LAST_MIDOFY_DATE`) VALUES ('GK_STEP4_KEEP_OLD', '다시 열렸습니다. 기존 단가는 유지됩니다. 재공을 수정 → 시산 → 덮어쓰기 확정.', 'Reopened. The old unit price is kept. Edit WIP → trial calculation → confirm overwrite.', 'Đã mở lại: đơn giá cũ vẫn giữ. Sửa DD → Tính thử → Xác nhận ghi đè.', '再開しました。以前の単価は残ります。仕掛を修正 → 試算 → 上書きを確定。', 'เปิดใหม่แล้ว ราคาต่อหน่วยเดิมยังอยู่ แก้งานระหว่างทำ → คำนวณทดลอง → ยืนยันเขียนทับ', '已重开。原单价保留。修改在产品 → 试算 → 确认覆盖。', '26-11-16 Simple costing', '2026-11-16 13:24:00', NULL);
INSERT INTO `t_message_info` (`KEY`, `KOR`, `ENG`, `VIET`, `JPN`, `THA`, `CHN`, `COMMENT`, `REG_DATE`, `LAST_MIDOFY_DATE`) VALUES ('GK_STEP4_NEED', '재공 방법을 고르고 % 또는 수량을 수정한 뒤 시산하고 확정하십시오.', 'Choose the WIP method, edit the percent or quantity, then trial-calculate and confirm.', 'Chọn phương pháp dở dang, chỉnh % hoặc SL, bấm Tính thử rồi Xác nhận.', '仕掛方法を選び、% または数量を直してから試算し、確定してください。', 'เลือกวิธีงานระหว่างทำ แก้ % หรือจำนวน แล้วคำนวณทดลองและยืนยัน', '请选择在产品方法，修改百分比或数量，再试算并确认。', '26-11-16 Simple costing', '2026-11-16 13:24:00', NULL);
INSERT INTO `t_message_info` (`KEY`, `KOR`, `ENG`, `VIET`, `JPN`, `THA`, `CHN`, `COMMENT`, `REG_DATE`, `LAST_MIDOFY_DATE`) VALUES ('GK_STEP4_PREVIEWED', '시산했습니다. 아직 덮어쓰지 않았습니다. 확정해야 공식 단가가 갱신됩니다.', 'Trial calculation is done and nothing is overwritten yet. Confirm to update the official unit price.', 'Đã tính thử — chưa ghi đè. Xác nhận mới cập nhật đơn giá chính thức.', '試算済みで、まだ上書きしていません。確定すると正式単価が更新されます。', 'คำนวณทดลองแล้ว ยังไม่เขียนทับ ยืนยันแล้วราคาต่อหน่วยทางการจึงอัปเดต', '已试算，尚未覆盖。确认后才更新正式单价。', '26-11-16 Simple costing', '2026-11-16 13:24:00', NULL);
INSERT INTO `t_message_info` (`KEY`, `KOR`, `ENG`, `VIET`, `JPN`, `THA`, `CHN`, `COMMENT`, `REG_DATE`, `LAST_MIDOFY_DATE`) VALUES ('GK_STEP4_SUB', '재공 → 155/154', 'WIP → 155/154', 'Dở dang → 155/154', '仕掛 → 155/154', 'งานระหว่างทำ → 155/154', '在产品 → 155/154', '26-11-16 Simple costing', '2026-11-16 13:24:00', NULL);
INSERT INTO `t_message_info` (`KEY`, `KOR`, `ENG`, `VIET`, `JPN`, `THA`, `CHN`, `COMMENT`, `REG_DATE`, `LAST_MIDOFY_DATE`) VALUES ('GK_STEP4_TITLE', '원가 계산 및 기록', 'Calculate and post product cost', 'Tính & ghi nhận giá thành', '原価の計算と計上', 'คำนวณและบันทึกต้นทุน', '计算并登记成本', '26-11-16 Simple costing', '2026-11-16 13:24:00', NULL);
INSERT INTO `t_message_info` (`KEY`, `KOR`, `ENG`, `VIET`, `JPN`, `THA`, `CHN`, `COMMENT`, `REG_DATE`, `LAST_MIDOFY_DATE`) VALUES ('GK_STEP5_BAND', '재고 방법으로 출고 단가를 다시 계산', 'Recalculate the issue price with the inventory method', 'Tính lại giá xuất theo phương pháp kho', '在庫方法で出庫単価を再計算', 'คำนวณราคาออกใหม่ตามวิธีคลัง', '按库存方法重算出库单价', '26-11-16 Simple costing', '2026-11-16 13:24:00', NULL);
INSERT INTO `t_message_info` (`KEY`, `KOR`, `ENG`, `VIET`, `JPN`, `THA`, `CHN`, `COMMENT`, `REG_DATE`, `LAST_MIDOFY_DATE`) VALUES ('GK_STEP5_BAND_DESC', '모든 경우에 출고 수량 × 당기 완제품 단가를 쓰지 않습니다. 데모는 기초 재고 + 당기 입고의 가중평균을 적용합니다.', 'Qty issued times this period''s finished-goods unit price is not used in every case. The demo applies a weighted average of opening stock plus receipts.', 'Không dùng SL xuất × đơn giá TP kỳ này cho mọi trường hợp. Demo áp dụng bình quân gia quyền tồn đầu + nhập kỳ.', 'すべての場合に出庫数量 × 当期完成品単価は使いません。デモは期首在庫 + 当期入庫の加重平均を適用します。', 'ไม่ได้ใช้จำนวนออก × ราคาต่อหน่วยสินค้าในงวดนี้ทุกกรณี ตัวอย่างใช้ถัวเฉลี่ยถ่วงน้ำหนักของยอดต้นงวดบวกของรับเข้า', '并非所有情况都用发出数量 × 本期成品单价。演示采用期初库存加本期入库的加权平均。', '26-11-16 Simple costing', '2026-11-16 13:24:00', NULL);
INSERT INTO `t_message_info` (`KEY`, `KOR`, `ENG`, `VIET`, `JPN`, `THA`, `CHN`, `COMMENT`, `REG_DATE`, `LAST_MIDOFY_DATE`) VALUES ('GK_STEP5_CONFIRM', 'INPUT_ID 기준으로 입고 단가를 갱신하고 출고 단가를 다시 계산한 뒤 VALUATION_COGS를 기록합니다. 계속하시겠습니까?', 'Update the receipt price by INPUT_ID, recalculate the issue price, and post VALUATION_COGS. Continue?', 'Cập nhật giá nhập theo INPUT_ID, tính lại giá xuất và ghi VALUATION_COGS. Tiếp tục?', 'INPUT_ID で入庫単価を更新し、出庫単価を再計算して VALUATION_COGS を記録します。続けますか？', 'อัปเดตราคารับตาม INPUT_ID คำนวณราคาออกใหม่ และบันทึก VALUATION_COGS ดำเนินการต่อหรือไม่', '按 INPUT_ID 更新入库单价，重算出库单价并写入 VALUATION_COGS。是否继续？', '26-11-16 Simple costing', '2026-11-16 13:24:00', NULL);
INSERT INTO `t_message_info` (`KEY`, `KOR`, `ENG`, `VIET`, `JPN`, `THA`, `CHN`, `COMMENT`, `REG_DATE`, `LAST_MIDOFY_DATE`) VALUES ('GK_STEP5_DONE', '평가가 기록되었습니다. REOPEN 후 다시 실행하면 같은 STABLE_KEY를 갱신하고 두 번째 전표는 만들지 않습니다.', 'Valuation is posted. Running again after REOPEN updates the same STABLE_KEY and does not create a second voucher.', 'Định giá đã ghi. Chạy lại sau REOPEN cập nhật cùng STABLE_KEY, không tạo chứng từ thứ hai.', '評価を記録しました。REOPEN 後の再実行は同じ STABLE_KEY を更新し、2枚目の伝票は作りません。', 'บันทึกการตีราคาแล้ว รันอีกครั้งหลัง REOPEN จะอัปเดต STABLE_KEY เดิม และไม่สร้างเอกสารที่สอง', '计价已入账。REOPEN 后再次运行会更新同一 STABLE_KEY，不生成第二张凭证。', '26-11-16 Simple costing', '2026-11-16 13:24:00', NULL);
INSERT INTO `t_message_info` (`KEY`, `KOR`, `ENG`, `VIET`, `JPN`, `THA`, `CHN`, `COMMENT`, `REG_DATE`, `LAST_MIDOFY_DATE`) VALUES ('GK_STEP5_HINT', '미리보기는 재고를 기록하지 않습니다. 확정해야 INPUT_ID, 출고 단가, VALUATION_COGS 전표가 갱신됩니다.', 'Preview does not post inventory. Confirm to update INPUT_ID, the issue price, and the VALUATION_COGS voucher.', 'Xem trước không ghi kho. Xác nhận mới cập nhật INPUT_ID, giá xuất và chứng từ VALUATION_COGS.', 'プレビューは在庫を記録しません。確定すると INPUT_ID、出庫単価、VALUATION_COGS 伝票が更新されます。', 'การดูล่วงหน้าไม่บันทึกคลัง ยืนยันแล้วจึงอัปเดต INPUT_ID ราคาออก และเอกสาร VALUATION_COGS', '预览不记库存。确认后才更新 INPUT_ID、出库单价和 VALUATION_COGS 凭证。', '26-11-16 Simple costing', '2026-11-16 13:24:00', NULL);
INSERT INTO `t_message_info` (`KEY`, `KOR`, `ENG`, `VIET`, `JPN`, `THA`, `CHN`, `COMMENT`, `REG_DATE`, `LAST_MIDOFY_DATE`) VALUES ('GK_STEP5_OK', '서버가 평가를 기록했습니다.', 'The server recorded the valuation.', 'Backend đã ghi nhận định giá.', 'サーバーが評価を記録しました。', 'เซิร์ฟเวอร์บันทึกการตีราคาแล้ว', '服务器已记录计价。', '26-11-16 Simple costing', '2026-11-16 13:24:00', NULL);
INSERT INTO `t_message_info` (`KEY`, `KOR`, `ENG`, `VIET`, `JPN`, `THA`, `CHN`, `COMMENT`, `REG_DATE`, `LAST_MIDOFY_DATE`) VALUES ('GK_STEP5_PREVIEW_OK', '출고 단가를 시산했습니다. 아직 덮어쓰지 않았습니다.', 'Issue price was trial-calculated and is not overwritten yet.', 'Đã tính thử giá xuất — chưa ghi đè.', '出庫単価を試算しました。まだ上書きしていません。', 'คำนวณทดลองราคาออกแล้ว ยังไม่เขียนทับ', '已试算出库单价，尚未覆盖。', '26-11-16 Simple costing', '2026-11-16 13:24:00', NULL);
INSERT INTO `t_message_info` (`KEY`, `KOR`, `ENG`, `VIET`, `JPN`, `THA`, `CHN`, `COMMENT`, `REG_DATE`, `LAST_MIDOFY_DATE`) VALUES ('GK_STEP5_SUB', '판매출고 → 632/155', 'Sales issue → 632/155', 'Xuất bán → 632/155', '販売出庫 → 632/155', 'ออกขาย → 632/155', '销售出库 → 632/155', '26-11-16 Simple costing', '2026-11-16 13:24:00', NULL);
INSERT INTO `t_message_info` (`KEY`, `KOR`, `ENG`, `VIET`, `JPN`, `THA`, `CHN`, `COMMENT`, `REG_DATE`, `LAST_MIDOFY_DATE`) VALUES ('GK_STEP5_TITLE', '출고 단가 재계산 및 대사', 'Recalculate and reconcile the issue price', 'Tính lại & đối chiếu giá xuất', '出庫単価の再計算と照合', 'คำนวณใหม่และกระทบยอดราคาออก', '重算并核对出库单价', '26-11-16 Simple costing', '2026-11-16 13:24:00', NULL);
INSERT INTO `t_message_info` (`KEY`, `KOR`, `ENG`, `VIET`, `JPN`, `THA`, `CHN`, `COMMENT`, `REG_DATE`, `LAST_MIDOFY_DATE`) VALUES ('GK_STEP6_BAND', 'B-I의 3단계 마감 엔진을 다시 호출', 'Call the B-I step 3 lock engine again', 'Gọi lại engine khóa sổ bước 3 của B-I', 'B-I の工程3締めエンジンを再呼び出し', 'เรียกเอนจินล็อกขั้นตอนที่ 3 ของ B-I อีกครั้ง', '再次调用 B-I 第3步结账引擎', '26-11-16 Simple costing', '2026-11-16 13:24:00', NULL);
INSERT INTO `t_message_info` (`KEY`, `KOR`, `ENG`, `VIET`, `JPN`, `THA`, `CHN`, `COMMENT`, `REG_DATE`, `LAST_MIDOFY_DATE`) VALUES ('GK_STEP6_BAND_DESC', 'G-K에서 직접 실행합니다. PROFIT_LOSS_REPORT를 실행하기 전에 제조원가와 매출원가 완료를 점검하십시오.', 'Run it directly in G-K. Check that product cost and COGS are complete before PROFIT_LOSS_REPORT.', 'Thực hiện trực tiếp trong G-K. Kiểm tra hoàn tất giá thành & giá vốn trước khi chạy PROFIT_LOSS_REPORT.', 'G-K で直接実行します。PROFIT_LOSS_REPORT の前に製造原価と売上原価の完了を確認してください。', 'ทำใน G-K โดยตรง ตรวจว่าต้นทุนผลิตและต้นทุนขายเสร็จก่อนเรียก PROFIT_LOSS_REPORT', '在 G-K 中直接执行。运行 PROFIT_LOSS_REPORT 前请确认生产成本和销售成本已完成。', '26-11-16 Simple costing', '2026-11-16 13:24:00', NULL);
INSERT INTO `t_message_info` (`KEY`, `KOR`, `ENG`, `VIET`, `JPN`, `THA`, `CHN`, `COMMENT`, `REG_DATE`, `LAST_MIDOFY_DATE`) VALUES ('GK_STEP6_CHECK_OK', '3단계 마감 조건이 유효합니다.', 'The step 3 lock conditions are valid.', 'Điều kiện khóa sổ bước 3 hợp lệ.', '工程3の締め条件は有効です。', 'เงื่อนไขล็อกขั้นตอนที่ 3 ถูกต้อง', '第3步结账条件有效。', '26-11-16 Simple costing', '2026-11-16 13:24:00', NULL);
INSERT INTO `t_message_info` (`KEY`, `KOR`, `ENG`, `VIET`, `JPN`, `THA`, `CHN`, `COMMENT`, `REG_DATE`, `LAST_MIDOFY_DATE`) VALUES ('GK_STEP6_CONFIRM', 'PeriodLock PROFIT_LOSS_REPORT를 실행합니다. DB의 단계가 DONE일 때만 성공으로 보고합니다. 계속하시겠습니까?', 'Run PeriodLock PROFIT_LOSS_REPORT. Success is reported only when the step on the database is DONE. Continue?', 'Chạy PeriodLock PROFIT_LOSS_REPORT. Chỉ báo thành công khi bước trên DB là DONE. Tiếp tục?', 'PeriodLock PROFIT_LOSS_REPORT を実行します。DB の工程が DONE のときだけ成功にします。続けますか？', 'เรียก PeriodLock PROFIT_LOSS_REPORT รายงานสำเร็จเฉพาะเมื่อขั้นตอนบนฐานข้อมูลเป็น DONE ดำเนินการต่อหรือไม่', '运行 PeriodLock PROFIT_LOSS_REPORT。仅当数据库上该步为 DONE 时才报成功。是否继续？', '26-11-16 Simple costing', '2026-11-16 13:24:00', NULL);
INSERT INTO `t_message_info` (`KEY`, `KOR`, `ENG`, `VIET`, `JPN`, `THA`, `CHN`, `COMMENT`, `REG_DATE`, `LAST_MIDOFY_DATE`) VALUES ('GK_STEP6_DONE', 'B6은 PeriodLock PROFIT_LOSS_REPORT를 호출합니다. 작업이 끝나기 전에 스스로 DONE으로 표시하지 않습니다.', 'B6 calls PeriodLock PROFIT_LOSS_REPORT. It does not mark itself DONE before the job finishes.', 'B6 gọi PeriodLock PROFIT_LOSS_REPORT. Không tự đánh dấu DONE nếu job chưa xong.', 'B6 は PeriodLock PROFIT_LOSS_REPORT を呼びます。ジョブ完了前に自ら DONE とはしません。', 'B6 เรียก PeriodLock PROFIT_LOSS_REPORT ไม่ตั้ง DONE เองถ้างานยังไม่เสร็จ', 'B6 调用 PeriodLock PROFIT_LOSS_REPORT。作业未完成前不会自行标为 DONE。', '26-11-16 Simple costing', '2026-11-16 13:24:00', NULL);
INSERT INTO `t_message_info` (`KEY`, `KOR`, `ENG`, `VIET`, `JPN`, `THA`, `CHN`, `COMMENT`, `REG_DATE`, `LAST_MIDOFY_DATE`) VALUES ('GK_STEP6_NEED', 'REOPENED 단계가 남아 있으면 마감할 수 없습니다. 6단계를 다시 열어도 이전 단계 결과는 바뀌지 않습니다.', 'Lock is blocked while a step is REOPENED. Reopening step 6 does not change earlier results.', 'Không khóa được nếu còn bước REOPENED. Mở lại bước 6 không đổi kết quả bước trước.', 'REOPENED の工程が残っていると締められません。工程6を再開しても前工程の結果は変わりません。', 'ล็อกไม่ได้ถ้ายังมีขั้นตอน REOPENED การเปิดขั้นตอนที่ 6 ใหม่ไม่เปลี่ยนผลขั้นตอนก่อน', '仍有 REOPENED 步骤时不能结账。重开第6步不改变前面步骤的结果。', '26-11-16 Simple costing', '2026-11-16 13:24:00', NULL);
INSERT INTO `t_message_info` (`KEY`, `KOR`, `ENG`, `VIET`, `JPN`, `THA`, `CHN`, `COMMENT`, `REG_DATE`, `LAST_MIDOFY_DATE`) VALUES ('GK_STEP6_OK', 'PeriodLock이 손익 마감을 기록했습니다.', 'PeriodLock recorded the profit-and-loss lock.', 'PeriodLock đã ghi nhận khóa lãi lỗ.', 'PeriodLock が損益締めを記録しました。', 'PeriodLock บันทึกการล็อกกำไรขาดทุนแล้ว', 'PeriodLock 已记录损益结账。', '26-11-16 Simple costing', '2026-11-16 13:24:00', NULL);
INSERT INTO `t_message_info` (`KEY`, `KOR`, `ENG`, `VIET`, `JPN`, `THA`, `CHN`, `COMMENT`, `REG_DATE`, `LAST_MIDOFY_DATE`) VALUES ('GK_STEP6_READY', '조건을 모두 점검했습니다. 기말 마감할 수 있습니다.', 'All conditions were checked. The period can be locked.', 'Đã kiểm tra đủ điều kiện. Có thể khóa sổ cuối kỳ.', '条件をすべて確認しました。期末締めができます。', 'ตรวจสอบเงื่อนไขครบแล้ว สามารถล็อกปลายงวด', '条件已全部检查。可以期末结账。', '26-11-16 Simple costing', '2026-11-16 13:24:00', NULL);
INSERT INTO `t_message_info` (`KEY`, `KOR`, `ENG`, `VIET`, `JPN`, `THA`, `CHN`, `COMMENT`, `REG_DATE`, `LAST_MIDOFY_DATE`) VALUES ('GK_STEP6_SUB', '손익, 월 마감', 'Profit and loss, month close', 'Lãi/lỗ, chốt tháng', '損益、月次締め', 'กำไรขาดทุน, ปิดเดือน', '损益、月末结账', '26-11-16 Simple costing', '2026-11-16 13:24:00', NULL);
INSERT INTO `t_message_info` (`KEY`, `KOR`, `ENG`, `VIET`, `JPN`, `THA`, `CHN`, `COMMENT`, `REG_DATE`, `LAST_MIDOFY_DATE`) VALUES ('GK_STEP6_TITLE', '3단계 마감', 'Step 3 lock', 'Khóa sổ bước 3', '工程3の締め', 'ล็อกขั้นตอนที่ 3', '锁定第3步', '26-11-16 Simple costing', '2026-11-16 13:24:00', NULL);
