INSERT INTO `t_message_info` (`KEY`, `KOR`, `ENG`, `VIET`, `JPN`, `THA`, `CHN`, `COMMENT`, `REG_DATE`, `LAST_MIDOFY_DATE`) VALUES ('GK_WIP_HINT_PCT', 'CLOSING_154 = (BEFORE_154 + 621) × (100 − %) / 100. %를 수정하거나 기말 재공을 직접 입력하면 %를 역산합니다.', 'CLOSING_154 = (BEFORE_154 + 621) × (100 − %) / 100. Edit the percent, or type the closing WIP to back into the percent.', 'CLOSING_154 = (BEFORE_154 + 621) × (100 − %) / 100. Có thể sửa % hoặc điền tay DD CK để tính ngược %.', 'CLOSING_154 = (BEFORE_154 + 621) × (100 − %) / 100。% を直すか、期末仕掛を手入力すると % を逆算します。', 'CLOSING_154 = (BEFORE_154 + 621) × (100 − %) / 100 แก้ % หรือกรอกงานระหว่างทำปลายงวดเพื่อคำนวณ % ย้อนกลับ', 'CLOSING_154 = (BEFORE_154 + 621) × (100 − %) / 100。可改百分比，或手工填写期末在产品以反算百分比。', '26-11-16 Simple costing', '2026-11-16 13:24:00', NULL);
INSERT INTO `t_message_info` (`KEY`, `KOR`, `ENG`, `VIET`, `JPN`, `THA`, `CHN`, `COMMENT`, `REG_DATE`, `LAST_MIDOFY_DATE`) VALUES ('GK_WIP_HINT_QTY', 'CLOSING_154 = (BEFORE_154 + 621) / (Q + Qdd) × Qdd. Q는 완제품 입고 수량입니다. Qdd = 0이면 기말 재공은 0입니다.', 'CLOSING_154 = (BEFORE_154 + 621) / (Q + Qdd) × Qdd. Q is the finished-goods receipt qty. Qdd = 0 means closing WIP is 0.', 'CLOSING_154 = (BEFORE_154 + 621) / (Q + Qdd) × Qdd. Q lấy từ SL nhập thành phẩm. Qdd = 0 → DD CK = 0.', 'CLOSING_154 = (BEFORE_154 + 621) / (Q + Qdd) × Qdd。Q は完成品入庫数量です。Qdd = 0 なら期末仕掛は 0 です。', 'CLOSING_154 = (BEFORE_154 + 621) / (Q + Qdd) × Qdd Q คือจำนวนรับสินค้าสำเร็จรูป Qdd = 0 แปลว่างานระหว่างทำปลายงวดเป็น 0', 'CLOSING_154 = (BEFORE_154 + 621) / (Q + Qdd) × Qdd。Q 为产成品入库数量。Qdd = 0 则期末在产品为 0。', '26-11-16 Simple costing', '2026-11-16 13:24:00', NULL);
